package com.wiseway.service;
import com.wiseway.api.ApiDtos.PlanBRequest; import com.wiseway.domain.*; import java.util.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class RecommendationServicePlanBTest { private RecommendationService service(){return new RecommendationService(new LocationService(),(a,b)->Optional.of(new RoutingProvider.Route(7200,1500,"","WISEWAY_CURATED_ROUTE")),new FareCalculationService());} private PlanBRequest request(PlanBScenario s){return new PlanBRequest("Sector 14","Main Campus",28.4595,77.0266,28.4456,77.0420,null,null,s,List.of(),null);} @Test void scenariosProduceExplicitStrategies(){var s=service();assertTrue(s.planB(request(PlanBScenario.RUNNING_LATE)).disclaimer().contains("shorter estimated duration"));assertTrue(s.planB(request(PlanBScenario.MISSED_SERVICE)).disclaimer().contains("missed bus"));assertTrue(s.planB(request(PlanBScenario.SAVE_MONEY)).disclaimer().contains("lowest estimated fare"));assertTrue(s.planB(request(PlanBScenario.EXTRA_TIME)).disclaimer().contains("cheaper options"));}}
